import{_ as a,o as i,c as n,a4 as e}from"./chunks/framework.B-wJupoK.js";const l="/assets/image-20250822220208906.D6urd86_.png",p="/assets/image-20250822223406702.BzoG_XjN.png",t="/assets/image-20250822223836842.DplF4a19.png",h="/assets/image-20250822220756310.T1jIqmR0.png",r="/assets/image-20250822220937178.CZFLnC_i.png",k="/assets/image-20250822221637968.CDdou3ki.png",o="/assets/image-20250822222118307.DGYMo5R5.png",g="/assets/image-20250822222134080.B_bc0AkH.png",m="/assets/image-20250822222206127.BqmQDQ7r.png",d="/assets/image-20250822222410511.CE18xtA1.png",E="/assets/image-20250822222452463.BQ8VWj1q.png",c="/assets/image-20250822225655054.wW62CQYz.png",y="/assets/image-20250822223258675.CJHnmYEl.png",u="/assets/wanshaoweixin.DWzIcicW.jpg",x=JSON.parse('{"title":"可可图片编辑 HarmonyOS 上架应用分享","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（1）上架应用分享/可可图片编辑 HarmonyOS 上架应用分享/可可图片编辑 HarmonyOS 上架应用分享.md","filePath":"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（1）上架应用分享/可可图片编辑 HarmonyOS 上架应用分享/可可图片编辑 HarmonyOS 上架应用分享.md","lastUpdated":1757677612000,"__rawMarkdown":"# 可可图片编辑 HarmonyOS 上架应用分享\\n\\n## 介绍\\n\\n**可可图片编辑** 原名 **图片编辑大师**，因为上架审核的时候 ，提示与一些已有应用重名，为了避免冲突，需要改名字，所以苦心思考了一分钟，就调整成 **可可图片编辑**。\\n\\n![image-20250822220208906](assets/image-20250822220208906.png)\\n\\n## 应用\\n\\n![image-20250822223406702](assets/image-20250822223406702.png)\\n\\n应用商店访问链接\\n\\n> https://appgallery.huawei.com/app/detail?id=tupianbmjidashi.qinglanzhuma.huawei&channelId=SHARE\\n\\n![image-20250822223836842](assets/image-20250822223836842.png)\\n\\n## 功能展示\\n\\n可可图片编辑提供了图片处理的六大核心功能\\n\\n- 图片压缩\\n- 图片裁剪\\n- 滤镜效果\\n- 添加水印\\n- 图片绘画\\n- 图片拼图\\n\\n![image-20250822220756310](assets/image-20250822220756310.png)\\n\\n其中比较有意思的是也实现了图片的分享功能，这个在开发的时候也是调试了一段时间。\\n\\n## ![image-20250822220937178](assets/image-20250822220937178.png)\\n\\n## 开发和上架过程\\n\\n这个APP的开发过程是可以说是有90%是AI完成的，确实也摸索出一些自己的心得，上架过程只被打回一次，后续再提交也就通过了，还是挺顺利。\\n\\n![image-20250822221637968](assets/image-20250822221637968.png)\\n\\n\\n\\n开发时间\\n\\n![image-20250822222118307](assets/image-20250822222118307.png)\\n\\n![image-20250822222134080](assets/image-20250822222134080.png)\\n\\n![image-20250822222206127](assets/image-20250822222206127.png)\\n\\n\\n\\n## 立项的初衷\\n\\n​\\t抱着学习的心态来做产品，是最好验收自己掌握技能与否的方法，也是让自己所有的投入得到成就感的最好的方式。\\n\\n之前就一直想着好好梳理下 HarmonyOS 中 关于 Image 相关 Kit的一些用法，正好就借这个机会来实现了。\\n\\n![image-20250822222410511](assets/image-20250822222410511.png)\\n\\n---\\n\\n![image-20250822222452463](assets/image-20250822222452463.png)\\n\\n\\n\\n能看到，这个Image的kit还是可以做不少的功能到，都可以直接在鸿蒙手机上来完成了。\\n\\n\\n\\n## 开发环境与技术栈\\n\\n- **开发工具**：DevEco Studio 5.0+\\n- **SDK版本**：HarmonyOS SDK API 14+\\n- **开发语言**：ArkTS\\n- **UI框架**：ArkUI\\n- **路由管理**：ZRouter 1.6.1\\n- **状态管理**：V2状态管理(@ComponentV2 + @Local/@Param)\\n\\n## 状态管理策略\\n\\n项目全面采用HarmonyOS V2状态管理方案，相比V1版本具有更好的性能和更简洁的API：\\n\\n```typescript\\n@Entry\\n@Route({ name: \'CompressionPage\', useTemplate: true })\\n@ComponentV2\\nexport struct CompressionPage {\\n  @Local selectedImage: ImageInfo | null = null;\\n  @Local compressionParams: CompressionParams = {\\n    quality: 80,\\n    scale: 1.0,\\n    format: ImageFormat.JPEG,\\n    type: CompressionType.QUALITY,\\n    mode: CompressionMode.MANUAL,\\n    keepAspectRatio: true\\n  };\\n  @Local compressionResult: CompressionResult | null = null;\\n  @Local operationState: OperationState = OperationState.IDLE;\\n}\\n```\\n\\n## 智能图片压缩算法\\n\\n图片压缩是应用的核心功能之一，我们实现了一套智能压缩算法，支持三种压缩模式：\\n\\n### 压缩参数接口设计\\n\\n```typescript\\nexport interface CompressionParams {\\n  quality: number;              // 压缩质量 (0-100)\\n  scale: number;               // 缩放比例 (0.1-1.0)\\n  format: ImageFormat;         // 目标格式\\n  type: CompressionType;       // 压缩类型\\n  mode: CompressionMode;       // 压缩模式\\n  keepAspectRatio: boolean;    // 是否保持宽高比\\n  maxFileSize?: number;        // 最大文件大小 (KB)\\n  maxWidth?: number;           // 最大宽度\\n  maxHeight?: number;          // 最大高度\\n}\\n```\\n\\n### 自适应压缩算法\\n\\n针对**按文件大小压缩**的需求，我们实现了基于二分查找的自适应压缩算法：\\n\\n```typescript\\nexport async function compressImageBySize(\\n  imageUri: string, \\n  params: CompressionParams\\n): Promise<CompressionResult> {\\n  const targetSize = (params.maxFileSize || 1024) * 1024; // 转换为字节\\n  \\n  // 二分查找最佳压缩参数\\n  let minQuality = 10;\\n  let maxQuality = params.quality;\\n  \\n  while (maxQuality - minQuality > 5) {\\n    const currentQuality = Math.floor((minQuality + maxQuality) / 2);\\n    \\n    // 尝试当前质量参数\\n    const compressedData = await compressWithQuality(imageUri, currentQuality);\\n    \\n    if (compressedData.byteLength <= targetSize) {\\n      minQuality = currentQuality;\\n    } else {\\n      maxQuality = currentQuality;\\n    }\\n  }\\n  \\n  return bestResult;\\n}\\n```\\n\\n![image-20250822225655054](assets/image-20250822225655054.png)\\n\\n## 后续计划\\n\\n后续继续分享这个应用的实现细节，敬请期待。\\n\\n\\n\\n## 以往文章\\n\\n- [懂你的HarmonyOS知识库更新了，已经来到10970个文档了](https://mp.weixin.qq.com/s/sMd0CGe54T2Eya8dPaEn2A)\\n- [鸿蒙开发者狂喜！5000 元 / 个应用的羊毛快来薅](https://mp.weixin.qq.com/s/KBy2CLpXjUoDZDTYuu_IKg)\\n- [AI编程神器！Trae+Claude4.0 简单配置 让 HarmonyOS 开发效率飙升](https://mp.weixin.qq.com/s/AsieJTX8RkixgaKyDrzddg)\\n\\n\\n\\n\\n\\n## 近期活动\\n\\n最近想要想要考取 HarmonyOS 基础或者高级证书，或者快要获取的同学都可以点击这个链接，[加入我的班级](https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248)，考取成功有机会获得鸿蒙礼盒一份。\\n\\n![image-20250822223258675](assets/image-20250822223258675.png)\\n\\n\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多HarmonyOS相关的咨询。\\n\\n![wanshaoweixin](assets/wanshaoweixin.jpg)"}'),b={name:"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（1）上架应用分享/可可图片编辑 HarmonyOS 上架应用分享/可可图片编辑 HarmonyOS 上架应用分享.md"};function F(A,s,D,C,_,S){return i(),n("div",null,[...s[0]||(s[0]=[e("",52)])])}const B=a(b,[["render",F]]);export{x as __pageData,B as default};
